import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The machinery is domain-general; tensor programs are the first domain","description":"","frontmatter":{"title":"The machinery is domain-general; tensor programs are the first domain","type":"adr","date":"2026-10-19T00:00:00.000Z","status":"proposed","status_note":"proposed (claim articulated in deck; porting work untested)"},"headers":[],"relativePath":"graphopt/project/adrs/0009-domain-generality.md","filePath":"vendored/graphopt/project/adrs/0009-domain-generality.md"}`),a={name:`graphopt/project/adrs/0009-domain-generality.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0009-—-the-machinery-is-domain-general-tensor-programs-are-the-first-domain" tabindex="-1">ADR-0009 — The machinery is domain-general; tensor programs are the first domain <a class="header-anchor" href="#adr-0009-—-the-machinery-is-domain-general-tensor-programs-are-the-first-domain" aria-label="Permalink to “ADR-0009 — The machinery is domain-general; tensor programs are the first domain”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The deck now claims the project is a general machine — rules as data on a categorical substrate, certification as the referee, cost as the score, discovery closed into a well-defined game with learned players. Nothing in that loop is tensor-specific. This ADR records what transfers to other domains and what each new domain must supply.</p><h2 id="decision-thesis" tabindex="-1">Decision / thesis <a class="header-anchor" href="#decision-thesis" aria-label="Permalink to “Decision / thesis”">​</a></h2><p>The machinery is domain-general. Domain-specificity lives in <em>data</em>, not mechanism:</p><ul><li>the substrate is a general arrow calculus (<code>kernel</code>/<code>host</code>)</li><li>the discovery loop (enumerate → measure → truth → novelty → pay → closure → cert) operates on terms and laws, not on tensor ops</li><li>the game layer&#39;s boards are injected per-domain (<code>DomainSpec</code> = feature schema + featurizer parts + legal-move enumerator — a domain is data, not a subclass)</li></ul><p>A new domain supplies exactly:</p><ol><li>its operations as host functions (the leaf vocabulary),</li><li>its laws expressible in the calculus (the base alphabet),</li><li>a cost signal (the score).</li></ol><p>The hard-earned pieces — certifying machine-authored rules, playing the search as a game — transfer unchanged.</p><h2 id="candidate-domains-named-not-yet-built" tabindex="-1">Candidate domains (named, not yet built) <a class="header-anchor" href="#candidate-domains-named-not-yet-built" aria-label="Permalink to “Candidate domains (named, not yet built)”">​</a></h2><ul><li><strong>Compiler IRs beyond tensors</strong> — instruction selection, algebraic simplification; any IR with equational laws.</li><li><strong>Query optimization</strong> — relational algebra is an equational theory; joins/filters are morphisms; cost models are mature.</li><li><strong>Signal processing</strong> — filter composition, FFT-algebra — linear algebra of another flavor.</li><li><strong>Protocols / crypto</strong> — equivalence-checking domains where the correctness gate is the load-bearing piece.</li></ul><h2 id="consequences-open-work" tabindex="-1">Consequences / open work <a class="header-anchor" href="#consequences-open-work" aria-label="Permalink to “Consequences / open work”">​</a></h2><ul><li>The claim is currently <em>design-level</em>: no second domain has been ported. The honest next test is one small non-tensor domain end-to-end (host ops + base laws + cost), measuring how much machinery actually reuses vs how much silently assumed tensors.</li><li><code>host-tensor</code>/<code>lib-tensor</code> are the tensor domain&#39;s data; an analogous <code>host-&lt;domain&gt;</code>/<code>lib-&lt;domain&gt;</code> pair is the porting unit.</li><li>Open question carried in the deck: whether the learned players transfer across domains (policy trained on <code>meta</code>/<code>search</code> boards playing a new domain&#39;s board) is unmeasured.</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};